import * as T from './three.module.js';
// Read status state rather than hit callbacks so remote fighters and monsters match.
export class FrostVisuals {
 constructor(scene,remove){this.scene=scene;this.remove=remove;this.states=new Map();this.time=0;}
 create(a){const group=new T.Group();for(let i=0;i<52;i++){const attached=i<24;const mesh=new T.Mesh(new T.OctahedronGeometry(attached?.065:.025,0),new T.MeshStandardMaterial({color:attached?0xb9eaff:0xe7fbff,emissive:0x398ec9,emissiveIntensity:attached?.45:1,transparent:true,opacity:.9,roughness:.25,depthWrite:false}));mesh.userData={attached,seed:i*.618,angle:i*2.4};group.add(mesh);}this.scene.add(group);const state={group};this.states.set(a,state);return state;}
 update(dt,actors){this.time+=dt;const active=new Set(actors.filter(a=>a.hp>0&&!a.dead&&(a.slow>0||a.frostSlow>0)));for(const [a,s] of this.states)if(!active.has(a)){this.remove(s.group);this.states.delete(a);}
 for(const a of active){if(!a.g)continue;const s=this.states.get(a)||this.create(a);s.group.visible=a.g.visible;s.group.position.set(a.x,0,a.z);const fade=Math.min(1,Math.max(a.slow||0,a.frostSlow||0)/.2),bones=a.g.userData.puppet?.lastPositions,names=['LeftHand','RightHand','LeftFoot','RightFoot','Spine','Head'];
 s.group.children.forEach((p,i)=>{const u=p.userData,angle=u.angle+a.g.rotation.y;if(u.attached){const bone=bones?.[names[i%names.length]];if(bone)p.position.copy(bone).sub(s.group.position).add(new T.Vector3(Math.cos(angle)*.09,Math.sin(i*3)*.08,Math.sin(angle)*.09));else if(a.monster){const y=((i%8)/7-.5)*1.05,r=Math.sqrt(Math.max(.02,.58*.58-y*y));p.position.set(Math.cos(angle)*r,.65+y,Math.sin(angle)*r);}else p.position.set(Math.cos(angle)*.32,.22+(i%8)*.14,Math.sin(angle)*.32);p.scale.set(1,.6+(i%3)*.4,.45);p.rotation.set(angle,i,angle*.3);p.material.opacity=.85*fade;}else{const phase=(this.time*.8+u.seed)%1,r=.3+phase*.55;p.position.set(Math.cos(angle)*r,1.5*(1-phase),Math.sin(angle)*r);p.rotation.set(this.time*2+i,angle,this.time+i);p.material.opacity=Math.sin(phase*Math.PI)*fade;p.scale.setScalar(.8+Math.sin(i)*.3);}});}}
 clear(){for(const s of this.states.values())this.remove(s.group);this.states.clear();}
}
